import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Custom CUDA kernel for fused min and subtract
min_sub_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void min_sub_kernel(const float* __restrict__ in_data,
                               float* __restrict__ out_data,
                               float scalar,
                               int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = (in_data[idx] < scalar) ? in_data[idx] : scalar;
        out_data[idx] = val - scalar;
    }
}

torch::Tensor min_sub_cuda(torch::Tensor input, torch::Tensor scalar_tensor) {
    auto scalar = scalar_tensor.item<float>();
    auto out = torch::empty_like(input);
    int size = input.numel();

    int blockSize = 256;
    int gridSize = (size + blockSize - 1) / blockSize;

    min_sub_kernel<<<gridSize, blockSize>>>(input.data_ptr<float>(),
                                           out.data_ptr<float>(),
                                           scalar,
                                           size);
    return out;
}
"""

min_sub_cpp_source = r"""
torch::Tensor min_sub_cuda(torch::Tensor input, torch::Tensor scalar_tensor);
"""

# Compile the inline CUDA code
min_sub = load_inline(
    name="min_sub",
    cpp_sources=min_sub_cpp_source,
    cuda_sources=min_sub_source,
    functions=["min_sub_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model that performs a matrix multiplication (via nn.Linear),
    then applies a fused CUDA kernel for 'min' and subtract operations.
    """
    def __init__(self, in_features, out_features, constant):
        super().__init__()
        self.linear = nn.Linear(in_features, out_features)
        self.constant = nn.Parameter(torch.tensor(constant, dtype=torch.float32))
        self.min_sub = min_sub

    def forward(self, x):
        x = self.linear(x)
        x = self.min_sub.min_sub_cuda(x, self.constant)
        return x

def get_inputs():
    batch_size = 128
    in_features = 10
    return [torch.randn(batch_size, in_features, device="cuda")]

def get_init_inputs():
    in_features = 10
    out_features = 5
    constant = 2.0
    return [in_features, out_features, constant]
